        public int findMedian(int arr[][]) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        int m = arr.length;
        int n = arr[0].length;

        int medianIndex = (m*n)/2+1;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                maxHeap.add(arr[i][j]);
                if(maxHeap.size()>medianIndex){
                    maxHeap.poll();
                }
            }
        }
        return maxHeap.peek();
    }



